			return plumbing.ZeroHash, err
		}

		newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, checkpointSubtree)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		newTreeHash, err = s.maybeMergeVercelConfig(ctx, newTreeHash)
		if err != nil {
			return plumbing.ZeroHash, err
		}

		commitMsg := s.buildCommitMessage(opts)
		return CreateCommit(ctx, s.repo, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
	})
}"},{"rank":5,"score":52.1618,"file_path":"cmd/entire/cli/checkpoint/store.go","start_line":115,"end_line":124,"focus_line":115,"snippet_start_line":115,"snippet_end_line":124,"symbol_start_line":115,"symbol_end_line":124,"language":"Go","kind":"method","symbol_id":"local/entire_cli_kernel_001:Go:cmd/entire/cli/checkpoint/store.go:method:GitStore.updatePrimaryRef","symbol_name":"updatePrimaryRef","qualified_name":"GitStore.updatePrimaryRef","signature":"func (s *GitStore) updatePrimaryRef(ctx context.Context, build func(parentHash, rootTreeHash plumbing.Hash) (plumbing.Hash, error)) error","signals":["graph:calls","graph:outgoing","graph:callers","complete-symbol"],"snippet":"func (s *GitStore) updatePrimaryRef(ctx context.Context, build func(parentHash, rootTreeHash plumbing.Hash) (plumbing.Hash, error)) error {
